PLURIELS = {
 ("%(n)s jour après la fin de la période", "%(n)s jours après la fin de la période"): ("%(n)s dag na het einde van de periode|%(n)s dagen na het einde van de periode", "%(n)s day after the end of the period|%(n)s days after the end of the period", "%(n)s Tag nach Ende des Zeitraums|%(n)s Tage nach Ende des Zeitraums", "%(n)s día tras el final del periodo|%(n)s días tras el final del periodo", "%(n)s giorno dopo la fine del periodo|%(n)s giorni dopo la fine del periodo", "%(n)s ημέρα μετά το τέλος της περιόδου|%(n)s ημέρες μετά το τέλος της περιόδου"),
}
LANGS = ["nl", "en", "de", "es", "it", "el"]
racine = sys.argv[1]
for i, l in enumerate(LANGS):
    chemin = f"{racine}/{l}/LC_MESSAGES/django.po"
    po = polib.pofile(chemin)
    existants = {(e.msgctxt, e.msgid) for e in po if not e.obsolete}
    nouveaux = [polib.POEntry(msgid=k, msgstr=v[i]) for k, v in T.items() if (None, k) not in existants]
    for (sing, plur), v in PLURIELS.items():
        if (None, sing) not in existants:
            a, b = v[i].split("|")
            nouveaux.append(polib.POEntry(msgid=sing, msgid_plural=plur, msgstr_plural={0: a, 1: b}))
    if nouveaux:
        with open(chemin, "a", encoding="utf-8") as f:
            for e in nouveaux:
                f.write("\n" + e.__unicode__(wrapwidth=79))
    polib.pofile(chemin).save_as_mofile(chemin[:-3] + ".mo")
    print(l, len(nouveaux), "entrées ajoutées")
